import argparse
import json
from pathlib import Path
from tqdm import tqdm
from langchain.text_splitter import RecursiveCharacterTextSplitter

# ---------- File Readers ----------
def read_pdf(path):
    import fitz  # PyMuPDF
    txts = []
    doc = fitz.open(path)
    for p in range(doc.page_count):
        txts.append(doc.load_page(p).get_text("text"))
    return "\n".join(txts).strip()

def read_txt(path):
    with open(path, "r", encoding="utf-8", errors="ignore") as f:
        return f.read().strip()

def read_docx(path):
    from docx import Document
    doc = Document(path)
    return "\n".join([p.text for p in doc.paragraphs if p.text]).strip()

def read_html(path):
    from bs4 import BeautifulSoup
    with open(path, "r", encoding="utf-8", errors="ignore") as f:
        return BeautifulSoup(f, "html.parser").get_text(separator="\n").strip()

def read_json_like(path):
    with open(path, "r", encoding="utf-8", errors="ignore") as f:
        txt = f.read().strip()
        try:
            obj = json.loads(txt)
            return json.dumps(obj, ensure_ascii=False, indent=2)
        except Exception:
            return txt

# Map file extensions to readers
EXT_TO_READER = {
    ".pdf": read_pdf,
    ".txt": read_txt,
    ".docx": read_docx,
    ".html": read_html,
    ".htm": read_html,
    ".json": read_json_like,
    ".jsonl": read_json_like,
}

# ---------- Main ----------
def main(folder, out_path="ipc_laws_chunks.json", chunk_size=2000, chunk_overlap=200):
    folder = Path(folder)
    assert folder.exists(), f"Folder {folder} does not exist"
    files = [p for p in folder.iterdir() if p.is_file()]
    if not files:
        print("No files found in", folder)
        return

    splitter = RecursiveCharacterTextSplitter(
        chunk_size=chunk_size,
        chunk_overlap=chunk_overlap
    )
